function get_config(): array { $row = db()->query('SELECT payload FROM settings WHERE id=1')->fetchColumn(); if (!$row) return default_config(); $saved=json_decode((string)$row,true); return is_array($saved) ? array_replace_recursive(default_config(), $saved) : default_config(); }
function save_config(array $config): void { $stmt=db()->prepare('INSERT INTO settings(id,payload,updated_at) VALUES(1,?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,updated_at=excluded.updated_at'); $stmt->execute([json_encode($config, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE), now()]); }
function public_path(string $path): string { $path = str_replace('\\','/', $path); $path = ltrim($path, '/'); if ($path === '' || str_contains($path, '..')) throw new RuntimeException('Invalid file path.'); $full=realpath(FILES_DIR . '/' . $path); $base=realpath(FILES_DIR); if (!$full || !$base || !str_starts_with($full, $base . DIRECTORY_SEPARATOR)) throw new RuntimeException('Invalid file path.'); return $full; }
function markdown(string $text): string { $text=h($text); $text=preg_replace('/\*\*(.+?)\*\*/s','<strong>$1</strong>',$text); $text=preg_replace('/\*(.+?)\*/s','<em>$1</em>',$text); $lines=preg_split('/\R/',$text); $out=''; foreach($lines as $line){$line=trim($line); if($line==='')continue; if(str_starts_with($line,'- '))$out.='<li>'.substr($line,2).'</li>'; else $out.='<p>'.$line.'</p>'; } return str_contains($out,'<li>') ? '<ul>'.$out.'</ul>' : $out; }

function api(string $path, string $method): void {
    if ($path === '/api/config/status' && $method==='GET') json_response(['isConfigured'=>(bool)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()]);
    if ($path === '/api/auth/me' && $method==='GET') { require_auth(); $s=db()->prepare('SELECT id,username,enabled FROM admins WHERE id=?');$s->execute([$_SESSION['admin_id']]);json_response(['user'=>$s->fetch(PDO::FETCH_ASSOC)]); }
    if ($path === '/api/auth/login' && $method==='POST') { $d=json_body();$s=db()->prepare('SELECT * FROM admins WHERE username=?');$s->execute([trim((string)($d['username']??'') )]);$a=$s->fetch(PDO::FETCH_ASSOC);if(!$a||!$a['enabled']||!password_verify((string)($d['password']??''),$a['password_hash']))json_response(['error'=>'Invalid username or password.'],401);session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['csrf']=bin2hex(random_bytes(24));json_response(['success'=>true,'user'=>['id'=>$a['id'],'username'=>$a['username']],'csrf'=>csrf_token()]); }
    if ($path === '/api/auth/logout' && $method==='POST') { require_csrf(); session_destroy(); json_response(['success'=>true]); }
    if ($path === '/api/setup' && $method==='POST') { if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0)json_response(['error'=>'Setup is already complete.'],403);$d=json_body();$u=trim((string)($d['username']??''));$p=(string)($d['password']??'');if($u===''||strlen($p)<8||$p!==($d['confirm']??''))json_response(['error'=>'Use a username and matching password of at least 8 characters.'],400);$s=db()->prepare('INSERT INTO admins(username,password_hash,created_at,updated_at) VALUES(?,?,?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT),now(),now()]);session_regenerate_id(true);$_SESSION['admin_id']=(int)db()->lastInsertId();$_SESSION['csrf']=bin2hex(random_bytes(24));json_response(['success'=>true]); }
    if ($path === '/api/settings' && $method==='GET') json_response(get_config());
    if ($path === '/api/settings' && $method==='POST') { require_auth();require_csrf();$d=json_body();if(!$d)json_response(['error'=>'Settings payload is required.'],400);save_config($d);json_response(['success'=>true]); }
    if ($path === '/api/messages' && $method==='POST') { $d=json_body();foreach(['name','email','subject','message'] as $k)if(trim((string)($d[$k]??''))==='')json_response(['error'=>'All message fields are required.'],400);if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))json_response(['error'=>'Please enter a valid email address.'],400);$s=db()->prepare('INSERT INTO messages(name,email,subject,message,created_at) VALUES(?,?,?,?,?)');$s->execute([trim($d['name']),trim($d['email']),trim($d['subject']),trim($d['message']),now()]);json_response(['success'=>true]); }
    if ($path === '/api/messages' && $method==='GET') { require_auth();$rows=db()->query('SELECT * FROM messages ORDER BY created_at DESC')->fetchAll(PDO::FETCH_ASSOC);json_response($rows); }
    if (preg_match('#^/api/messages/(\d+)$#',$path,$m)) { require_auth();require_csrf();if($method==='PUT'){ $d=json_body();$s=db()->prepare('UPDATE messages SET read=? WHERE id=?');$s->execute([(int)!empty($d['read']),$m[1]]);json_response(['success'=>true]); } if($method==='DELETE'){db()->prepare('DELETE FROM messages WHERE id=?')->execute([$m[1]]);json_response(['success'=>true]);} }
    if ($path === '/api/files' && $method==='GET') { require_auth();$dir=trim((string)($_GET['path']??''),'/');$root=$dir?public_path($dir):FILES_DIR;$items=[];foreach(scandir($root) as $name){if($name==='.'||$name==='..')continue;$full=$root.'/'.$name;$relative=($dir?$dir.'/':'').$name;$items[]=['name'=>$name,'path'=>'/'.$relative,'isDirectory'=>is_dir($full),'size'=>is_file($full)?filesize($full):0,'updatedAt'=>date('c',filemtime($full))];}json_response($items); }
    if ($path === '/api/files/upload' && $method==='POST') { require_auth();require_csrf();$dir=trim((string)($_GET['path']??''),'/');$target=$dir?public_path($dir):FILES_DIR;if(!isset($_FILES['files']))json_response(['error'=>'No files uploaded.'],400);$saved=[];foreach((array)$_FILES['files']['name'] as $i=>$name){$safe=preg_replace('/[^a-zA-Z0-9._ -]/','_',basename($name));if(!is_uploaded_file($_FILES['files']['tmp_name'][$i]))continue;if(!move_uploaded_file($_FILES['files']['tmp_name'][$i],$target.'/'.$safe))json_response(['error'=>'Upload failed.'],500);$saved[]=$safe;}json_response(['success'=>true,'files'=>$saved]); }
    if ($path === '/api/files/create-folder' && $method==='POST') { require_auth();require_csrf();$d=json_body();$folder=trim((string)($d['path']??''),'/');if($folder==='')json_response(['error'=>'Folder path is required.'],400);$parent=dirname($folder);$target=$parent==='.'?FILES_DIR:public_path($parent);$name=basename($folder);if(!preg_match('/^[a-zA-Z0-9._ -]+$/',$name))json_response(['error'=>'Invalid folder name.'],400);if(!mkdir($target.'/'.$name,0775,true)&&!is_dir($target.'/'.$name))json_response(['error'=>'Unable to create folder.'],500);json_response(['success'=>true]); }
    if ($path === '/api/files/delete' && $method==='DELETE') { require_auth();require_csrf();$d=json_body();$target=public_path((string)($d['path']??''));if(is_dir($target)){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($target,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $item)$item->isDir()?rmdir($item->getPathname()):unlink($item->getPathname());rmdir($target);}else unlink($target);json_response(['success'=>true]); }
    if ($path === '/api/files/content' && $method==='GET') { require_auth();$target=public_path((string)($_GET['path']??''));if(filesize($target)>2097152)json_response(['error'=>'File is too large to edit.'],413);json_response(['content'=>file_get_contents($target)]); }
    if ($path === '/api/files/content' && $method==='POST') { require_auth();require_csrf();$d=json_body();$target=public_path((string)($d['path']??''));if(strlen((string)($d['content']??''))>2097152)json_response(['error'=>'File is too large to edit.'],413);file_put_contents($target,(string)$d['content'],LOCK_EX);json_response(['success'=>true]); }
    if ($path === '/api/files/shorten' && $method==='POST') { require_auth();require_csrf();$d=json_body();$file=(string)($d['path']??'');$target=public_path($file);if(!is_file($target))json_response(['error'=>'File not found.'],404);$id=bin2hex(random_bytes(4));db()->prepare('INSERT INTO file_links(id,path,created_at) VALUES(?,?,?)')->execute([$id,'/'.ltrim($file,'/'),now()]);json_response(['id'=>$id]); }
    if (preg_match('#^/api/files/link/([a-f0-9]{8})$#',$path,$m) && $method==='GET') { $s=db()->prepare('SELECT path FROM file_links WHERE id=?');$s->execute([$m[1]]);$file=$s->fetchColumn();if(!$file)json_response(['error'=>'Link not found.'],404);$target=public_path((string)$file);json_response(['name'=>basename($target),'path'=>$file,'isDirectory'=>false,'size'=>filesize($target),'updatedAt'=>date('c',filemtime($target))]); }
    json_response(['error'=>'Not found'],404);
}

