function render_admin(array $config): void { ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Panel</title><link rel="stylesheet" href="/assets/styles.css"></head><body class="admin-body"><div class="admin-shell"><aside class="admin-sidebar"><div class="brand">tangy.</div><button data-admin-section="main">Overview</button><button data-admin-section="persona">Profile</button><button data-admin-section="collections">Collections</button><button data-admin-section="contact">Contact</button><button data-admin-section="donations">Donations</button><button data-admin-section="messages">Messages</button><button id="logout">Log out</button></aside><main class="admin-main"><div class="admin-header"><h1>Admin Panel</h1><a href="/">View site</a></div><section class="admin-section active" data-admin-panel="main"><div class="stats"><div><b>Profile</b><span>Public and live</span></div><div><b data-message-count>0</b><span>Inbox messages</span></div></div><div class="box"><h2>Settings manager</h2><p class="muted">The public layout is unchanged. Edit the JSON configuration below, then save.</p><textarea id="settings-json" rows="28"><?=h(json_encode($config,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?></textarea><button id="save-settings">Save settings</button><p class="form-message" id="settings-message"></p></div></section><section class="admin-section" data-admin-panel="messages"><div class="box"><h2>Inbox</h2><div id="messages-list"><p class="muted">Loading messages…</p></div></div></section><section class="admin-section" data-admin-panel="persona"><div class="box"><h2>Profile</h2><p class="muted">Use the Settings manager to update profile text, images, and metadata without changing the UI.</p></div></section><section class="admin-section" data-admin-panel="collections"><div class="box"><h2>Collections</h2><p class="muted">Use the Settings manager to update setup, projects, communities, and links.</p></div></section><section class="admin-section" data-admin-panel="contact"><div class="box"><h2>Contact</h2><p class="muted">Contact form submissions are stored in the inbox.</p></div></section><section class="admin-section" data-admin-panel="donations"><div class="box"><h2>Donations</h2><p class="muted">Donation methods are managed in the settings JSON.</p></div></section></main></div><script>window.CSRF=<?=json_encode(csrf_token())?>;</script><script src="/assets/admin.js"></script></body></html><?php }

ensure_storage(); $uri=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH) ?: '/'; $method=$_SERVER['REQUEST_METHOD']??'GET';
if(str_starts_with($uri,'/api/')) api($uri,$method);
if($uri==='/assets/styles.css'){header('Content-Type:text/css');readfile(ROOT.'/assets/styles.css');exit;}
if($uri==='/assets/app.js'){header('Content-Type:application/javascript');readfile(ROOT.'/assets/app.js');exit;}
if($uri==='/assets/admin.js'){header('Content-Type:application/javascript');readfile(ROOT.'/assets/admin.js');exit;}
if($uri==='/admin/setup'){if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0){header('Location:/admin/login');exit;}render_login(true);exit;}
if($uri==='/admin/login'){if(!empty($_SESSION['admin_id'])){header('Location:/admin');exit;}render_login(false);exit;}
if($uri==='/admin'){if(empty($_SESSION['admin_id'])){header('Location:/admin/login');exit;}render_admin(get_config());exit;}
if(preg_match('#^/download/([a-f0-9]{8})$#',$uri,$m)){ $s=db()->prepare('SELECT path FROM file_links WHERE id=?');$s->execute([$m[1]]);$file=$s->fetchColumn();if(!$file){http_response_code(404);exit('File not found.');}try{$target=public_path((string)$file);}catch(Throwable){http_response_code(404);exit('File not found.');}header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($target).'"');header('Content-Length: '.filesize($target));readfile($target);exit; }
if(preg_match('#^/([a-zA-Z0-9_-]+)$#',$uri,$m)){foreach(get_config()['redirects']??[] as $r){if(strtolower((string)($r['slug']??''))===strtolower($m[1])){header('Location: '.(preg_match('#^https?://#i',$r['url'])?$r['url']:'https://'.$r['url']),true,302);exit;}}}
if(in_array($uri,['/400','/401','/403','/404','/503'],true)){http_response_code((int)substr($uri,1));?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/styles.css"><title>Error</title></head><body class="error-page"><h1><?=h(substr($uri,1))?></h1><p><?=h(get_config()['errorPages'][substr($uri,1)]??'Something went wrong.')?></p><a href="/">Home</a></body></html><?php exit;}
render_public(get_config());
